// ==========================================
// SEATING DIAGRAM TEMPLATES
// ==========================================

export function generateSleeper111Seats(vehicleId: string): SeatingDiagram {
  const seats: SeatCoordinate[] = [];
  const rows = [1, 2, 3, 4, 5, 6, 7];
  const cols = ["A", "B", "C"];

  rows.forEach((row, rIdx) => {
    cols.forEach((col, cIdx) => {
      const isOccupied = (row + cIdx) % 3 === 0;
      seats.push({
        id: `${row}${col}`,
        row,
        column: col,
        type: "SLEEPER_SUITE",
        status: isOccupied ? "OCCUPIED" : "AVAILABLE",
        deck: "SINGLE",
        x: 18 + cIdx * 32,
        y: 12 + rIdx * 12,
        pricePremiumRp: 75000,
        features: ["150_DEGREE_RECLINE", "24INCH_AVOD_SCREEN", "USB_C_FAST_CHARGE", "PRIVACY_CURTAIN"],
      });
    });
  });

  return {
    id: `seat-diag-${vehicleId}`,
    vehicleId,
    layoutType: "SLEEPER_1_1_1",
    totalSeats: seats.length,
    availableSeats: seats.filter((s) => s.status === "AVAILABLE").length,
    seats,
  };
}

export function generateSuperExec21Seats(vehicleId: string): SeatingDiagram {
  const seats: SeatCoordinate[] = [];
  const rows = [1, 2, 3, 4, 5, 6, 7];

  rows.forEach((row, rIdx) => {
    // Left pair: A, B
    ["A", "B"].forEach((col, cIdx) => {
      const isOccupied = (row * 2 + cIdx) % 4 === 0;
      seats.push({
        id: `${row}${col}`,
        row,
        column: col,
        type: "EXECUTIVE_RECLINER",
        status: isOccupied ? "OCCUPIED" : "AVAILABLE",
        deck: "SINGLE",
        x: 15 + cIdx * 20,
        y: 12 + rIdx * 12,
        pricePremiumRp: 35000,
        features: ["LEG_REST", "USB_PORT", "CUP_HOLDER", "HEADREST_WING"],
      });
    });

    // Right single: C
    const isOccupied = (row * 3) % 5 === 0;
    seats.push({
      id: `${row}C`,
      row,
      column: "C",
      type: "EXECUTIVE_RECLINER",
      status: isOccupied ? "OCCUPIED" : "AVAILABLE",
      deck: "SINGLE",
      x: 75,
      y: 12 + rIdx * 12,
      pricePremiumRp: 45000,
      features: ["SINGLE_VIP_SEAT", "LEG_REST", "USB_PORT", "READING_LIGHT"],
    });
  });

  return {
    id: `seat-diag-${vehicleId}`,
    vehicleId,
    layoutType: "EXECUTIVE_2_1",
    totalSeats: seats.length,
    availableSeats: seats.filter((s) => s.status === "AVAILABLE").length,
    seats,
  };
}

export function generateExecutive22Seats(vehicleId: string): SeatingDiagram {
  const seats: SeatCoordinate[] = [];
  const rows = [1, 2, 3, 4, 5, 6, 7, 8];

  rows.forEach((row, rIdx) => {
    ["A", "B", "C", "D"].forEach((col, cIdx) => {
      const isOccupied = (row + cIdx) % 3 === 1;
      const xPos = cIdx < 2 ? 14 + cIdx * 16 : 54 + (cIdx - 2) * 16;
      seats.push({
        id: `${row}${col}`,
        row,
        column: col,
        type: "STANDARD_COACH",
        status: isOccupied ? "OCCUPIED" : "AVAILABLE",
        deck: "SINGLE",
        x: xPos,
        y: 10 + rIdx * 10.5,
        pricePremiumRp: 0,
        features: ["FOOTREST", "RECLINING_BACKREST", "USB_OUTLET"],
      });
    });
  });

  return {
    id: `seat-diag-${vehicleId}`,
    vehicleId,
    layoutType: "SUPER_EXEC_2_2",
    totalSeats: seats.length,
    availableSeats: seats.filter((s) => s.status === "AVAILABLE").length,
    seats,
  };
}

export function generateCommuterLongitudinalSeats(vehicleId: string): SeatingDiagram {
  const seats: SeatCoordinate[] = [];

  // Left bench 12 seats
  for (let i = 1; i <= 12; i++) {
    const isPriority = i <= 3;
    seats.push({
      id: `L-${i}`,
      row: i,
      column: "L",
      type: isPriority ? "PRIORITY_ACCESSIBLE" : "LONGITUDINAL_BENCH",
      status: i % 2 === 0 ? "OCCUPIED" : "AVAILABLE",
      deck: "SINGLE",
      x: 10,
      y: 8 + (i - 1) * 7.5,
      pricePremiumRp: 0,
      features: isPriority ? ["PRIORITY_SEAT_PREGNANT_ELDERLY", "GRAB_HANDLE"] : ["STAINLESS_BENCH", "OVERHEAD_STRAP"],
    });
  }

  // Right bench 12 seats
  for (let i = 1; i <= 12; i++) {
    const isWheelchair = i === 12;
    seats.push({
      id: `R-${i}`,
      row: i,
      column: "R",
      type: isWheelchair ? "WHEELCHAIR_BAY" : "LONGITUDINAL_BENCH",
      status: isWheelchair ? "AVAILABLE" : i % 3 === 0 ? "OCCUPIED" : "AVAILABLE",
      deck: "SINGLE",
      x: 90,
      y: 8 + (i - 1) * 7.5,
      pricePremiumRp: 0,
      features: isWheelchair ? ["WHEELCHAIR_LOCK", "EMERGENCY_BUTTON"] : ["STAINLESS_BENCH", "OVERHEAD_STRAP"],
    });
  }

  return {
    id: `seat-diag-${vehicleId}`,
    vehicleId,
    layoutType: "COMMUTER_LONGITUDINAL",
    totalSeats: seats.length,
    availableSeats: seats.filter((s) => s.status === "AVAILABLE").length,
    seats,
  };
}

