export function generateKRLSF12Carriages(trainCode: string): VehicleCarriageTelemetry[] {
  const cars: VehicleCarriageTelemetry[] = [];
  const configs = [
    { code: "KuHa 204", type: "CAB_CAR" as const, name: "Kereta 1: Khusus Wanita (KKW Depan)", panto: false, cap: 180, occ: 55, temp: 21.5 },
    { code: "MoHa 204", type: "PANTOGRAPH_MOTOR" as const, name: "Kereta 2: Motor Traksi & Pantograf", panto: true, cap: 185, occ: 78, temp: 22.0 },
    { code: "MoHa 205", type: "MOTOR_CAR" as const, name: "Kereta 3: Motor Traksi Tengah", panto: false, cap: 185, occ: 82, temp: 22.2 },
    { code: "SaHa 205", type: "TRAILER_CAR" as const, name: "Kereta 4: Trailer Tengah Non-Traksi", panto: false, cap: 185, occ: 80, temp: 22.1 },
    { code: "MoHa 204", type: "PANTOGRAPH_MOTOR" as const, name: "Kereta 5: Motor Traksi & Pantograf", panto: true, cap: 185, occ: 85, temp: 22.4 },
    { code: "MoHa 205", type: "MOTOR_CAR" as const, name: "Kereta 6: Motor Traksi Tengah", panto: false, cap: 185, occ: 88, temp: 22.3 },
    { code: "SaHa 205", type: "TRAILER_CAR" as const, name: "Kereta 7: Trailer Tengah Non-Traksi", panto: false, cap: 185, occ: 79, temp: 22.0 },
    { code: "MoHa 204", type: "PANTOGRAPH_MOTOR" as const, name: "Kereta 8: Motor Traksi & Pantograf", panto: true, cap: 185, occ: 84, temp: 22.2 },
    { code: "MoHa 205", type: "MOTOR_CAR" as const, name: "Kereta 9: Motor Traksi Tengah", panto: false, cap: 185, occ: 80, temp: 22.1 },
    { code: "SaHa 205", type: "TRAILER_CAR" as const, name: "Kereta 10: Trailer Tengah Non-Traksi", panto: false, cap: 185, occ: 74, temp: 22.0 },
    { code: "MoHa 204", type: "PANTOGRAPH_MOTOR" as const, name: "Kereta 11: Motor Traksi & Pantograf", panto: true, cap: 185, occ: 68, temp: 21.8 },
    { code: "KuHa 205", type: "CAB_CAR" as const, name: "Kereta 12: Khusus Wanita (KKW Belakang)", panto: false, cap: 180, occ: 48, temp: 21.4 },
  ];

  configs.forEach((cfg, idx) => {
    cars.push({
      carIndex: idx + 1,
      carCode: `${cfg.code}-${trainCode}-${(idx + 1).toString().padStart(2, "0")}`,
      carType: cfg.type,
      carTypeName: cfg.name,
      occupancyPercent: cfg.occ,
      passengerCount: Math.round((cfg.occ / 100) * cfg.cap),
      maxCapacity: cfg.cap,
      acTemperatureC: cfg.temp,
      acStatus: "OPTIMAL",
      pantographActive: cfg.panto,
      tractionMotorActive: cfg.type.includes("MOTOR"),
      prioritySeatsCount: 16,
      wheelchairAccessible: idx === 0 || idx === 11,
      cctvActive: true,
      wifiStatus: "ONLINE",
      doorsStatus: "CLOSED_LOCKED",
    });
  });

  return cars;
}

